import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import {
  resultCodeTransactionsActionResultCodeSchema,
  type ResultCodeTransactionsActionResultCode,
} from "./result-code-transactions-action-result-code.js";
import {
  typeTransactionsActionTypeSchema,
  type TypeTransactionsActionType,
} from "./type-transactions-action-type.js";

export type Action67 = {
  /** A unique identifier generated by the platform to identify an action. */
  id?: string;
  /** Indicates the specific action taken. */
  type?: TypeTransactionsActionType;
  /** Time indicating when the transaction was created in ISO-8601 format. */
  timeCreated?: Date;
  /**
   * The result of the action executed.
   * * `SUCCESS` - indicates the action executed successfully.
   * * `DECLINED` - indicates the result of the action was to DECLINE it. This means to consider
   *   that payment is not allowed and goods or services should not be provided. For transaction
   *   processing this means the payment method declined the transaction.
   * * `PENDING` - indicates the result is not known but a final result will be subsequently
   *   provided. When the result is known the value can be updated to a SUCCESS, DECLINED or ERROR
   *   code.
   * * `ERROR` - indicates the action was PENDING but when the final result was known, it had
   *   errored.
   */
  resultCode?: ResultCodeTransactionsActionResultCode;
  /** The id of the app that was used to create the token. */
  appId?: string;
  /** The name of the app the user gave to the application. */
  appName?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

const action67Properties: s.Shape<Action67> = {
  id: s.optional(s.string()),
  type: s.optional(s.lazy(() => typeTransactionsActionTypeSchema)),
  timeCreated: s.optional(s.dateTime()),
  resultCode: s.optional(s.lazy(() => resultCodeTransactionsActionResultCodeSchema)),
  appId: s.optional(s.string()),
  appName: s.optional(s.string()),
  _keysMap: {
    timeCreated: "time_created",
    resultCode: "result_code",
    appId: "app_id",
    appName: "app_name",
  },
};

export const action67InternalSchema: Schema<Action67> = s.object<Action67>(action67Properties, {
  additionalProperties: s.json(),
});

export const action67Schema: Schema<Action67> = s.lazySchema(() =>
  s.object<Action67>(
    {
      ...action67Properties,
      id: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      appId: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      appName: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
    },
    { additionalProperties: s.json() },
  ),
);
